from intervals import merge


def test_merge_overlapping_ranges():
    assert merge([(1, 3), (2, 6), (8, 10)]) == [(1, 6), (8, 10)]


def test_merge_sorts_and_joins_at_shared_endpoints():
    assert merge([(5, 6), (1, 2), (2, 4)]) == [(1, 4), (5, 6)]


def test_merge_nests_contained_ranges():
    assert merge([(1, 4), (2, 3)]) == [(1, 4)]


def test_merge_edge_cases():
    assert merge([]) == []
    assert merge([(4, 5)]) == [(4, 5)]
